ee:message.ee:set-payload:
%dw 2.0 output text/plain
fun safe(v,d="N/A") = if (v == null or (v is String and trim(v) == "")) d else v
var integration = vars.integration default vars.initialVariables default {} var sysInfo = vars.systemInformation default {} var cdm = (vars.initialPayload default [])[0].b2bMessage default {} var header = cdm.header default {}
var senderKey = header.senderId default "" var vendorId = if (senderKey != "") (p("partner.inbound." ++ senderKey) default p("partner.outbound." ++ senderKey) default "N/A") else "N/A"
var poNumber = safe(header.poNumber) var percentage = vars.isValid.validationErrors.shipToMatchPercentage default vars.isValid.validationErrors.shipToMatchPercentage default null
var data = { matchPercentage: (percentage as Number) as String {format: "00.00"} ++ "%",, flowDirection: if(lower(safe(integration.source,"APM"))=="apm") "INBOUND" else "OUTBOUND", documentType: safe(integration."integration-type", safe(header.documentType,"API")), warningTitle: "Address Match Warning", bannerColor: "#f59e0b", warningType: "ADDRESS_MATCH_WARNING", warningCategory: "VALIDATION", status: "PROCESSED WITH WARNING", companyName: vars.purchaseOrderData.value.company_no[0] default "N/A", vendorName: vendorId, route: safe(integration.source,"APM") ++ " → Mule → " ++ safe(integration.target,"P21"), businessKey: "PO " ++ poNumber, timestamp: now() as String {format:"yyyy-MM-dd HH:mm:ss"}, transmissionId: safe(header.transmissionId), keyLabel: "Correlation ID", key: correlationId default uuid(), transactionType: safe(integration."integration-type", safe(header.documentType,"API")), appName: p("api.name") default "Mule Application", environment: upper(p("mule.env") default "DEV"), message: "Purchase Order " ++ poNumber ++ " was processed successfully with a warning.", warningDescription: "The Ship-To address matched " ++ ((percentage default "N/A") as String) ++ "% with the corresponding address in P21." ++ "\nThe transaction was processed because the configured warning threshold is between " ++ Mule::p('shipToValidation.lowerLimit') ++ "%" ++ "and" ++ Mule::p('shipToValidation.upperLimit') ++ "%.", warningResolution: "No action is required. Please review the Ship-To address if necessary." }
var template = readUrl("classpath://templates/warning-template.html","text/plain") --- template replace /\$\{(\w+)\}/ with ((m) -> (data[m[1]] as String) default "")
